import React, { useState } from 'react';
import { StatusBadge, BatteryBar } from './UIKit';

export default function FleetList({ fleet, selectedVehicle, onSelect }) {
  const [filter, setFilter] = useState('all');
  const [search, setSearch] = useState('');

  const filtered = fleet.filter(v => {
    const matchFilter = filter === 'all' || v.status === filter;
    const matchSearch = v.id.toLowerCase().includes(search.toLowerCase()) ||
      (v.route && v.route.toLowerCase().includes(search.toLowerCase()));
    return matchFilter && matchSearch;
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', gap: 10 }}>
      <input
        value={search}
        onChange={e => setSearch(e.target.value)}
        placeholder="Search vehicles..."
        style={{
          background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)',
          borderRadius: 8, padding: '7px 12px', color: '#e0eaff',
          fontSize: 11, fontFamily: 'monospace', width: '100%',
        }}
      />
      <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
        {['all','autonomous','takeover_needed','manual_control'].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{
            background: filter === f ? 'rgba(0,207,255,0.15)' : 'rgba(255,255,255,0.03)',
            border: `1px solid ${filter === f ? '#00cfff55' : 'rgba(255,255,255,0.07)'}`,
            color: filter === f ? '#00cfff' : '#556677',
            fontSize: 9, padding: '3px 8px', borderRadius: 12, cursor: 'pointer',
            fontFamily: 'monospace', textTransform: 'uppercase',
          }}>{f.replace('_', ' ')}</button>
        ))}
      </div>
      <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 6 }}>
        {filtered.map(vehicle => {
          const isSelected = selectedVehicle?.id === vehicle.id;
          const hasCritical = vehicle.alerts?.some(a => a.type === 'CRITICAL');
          return (
            <div key={vehicle.id} onClick={() => onSelect(vehicle)} style={{
              background: isSelected ? 'rgba(0,207,255,0.08)' : hasCritical ? 'rgba(255,34,68,0.07)' : 'rgba(255,255,255,0.025)',
              border: `1px solid ${isSelected ? '#00cfff44' : hasCritical ? '#ff224433' : 'rgba(255,255,255,0.06)'}`,
              borderRadius: 10, padding: '10px 12px', cursor: 'pointer', transition: 'all 0.15s',
            }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 6 }}>
                <span style={{ fontSize: 13, fontWeight: 700, color: '#e0eaff', fontFamily: 'monospace' }}>
                  {vehicle.id}{hasCritical && <span style={{ marginLeft: 6, fontSize: 10, color: '#ff2244' }}>⚠</span>}
                </span>
                <StatusBadge status={vehicle.status} small />
              </div>
              <BatteryBar value={vehicle.battery} />
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 6, fontSize: 10, color: '#556677', fontFamily: 'monospace' }}>
                <span>{vehicle.route || '—'}</span>
                <span>{Math.round(vehicle.speed)} km/h · {vehicle.passengers} pax</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
